# Medya dosyalarını tarihe göre arşivle
$gelenPath = "gelen"
$arsivRoot = "arsiv"

# Medya dosyası uzantıları
$mediaExtensions = @(".jpg", ".jpeg", ".png", ".mp4", ".mov")

# Tarih eşleşmeleri için regex (YYYYMMDD veya YYYY-MM-DD)
$tarihRegex1 = "\d{4}(0[1-9]|1[0-2])(0[1-9]|[12]\d|3[01])"
$tarihRegex2 = "\d{4}-\d{2}-\d{2}"

# Tarihi bulunamayan dosyalar için klasör
$tarihsizPath = "$arsivRoot\tarihsiz"
if (!(Test-Path $tarihsizPath)) {
    New-Item -ItemType Directory -Path $tarihsizPath -Force
}

# Alt klasörlerdeki dosyalara erişmek için bir liste oluşturuyoruz
$files = Get-ChildItem -Path $gelenPath -Recurse -File

foreach ($file in $files) {
    # Dosyanın uzantısı medya uzantılarından mı?
    if ($mediaExtensions -contains $file.Extension.ToLower()) {
        # Dosya adından tarih bilgisini al
        $fileName = $file.BaseName
        $tarihMatch1 = [regex]::Match($fileName, $tarihRegex1)
        $tarihMatch2 = [regex]::Match($fileName, $tarihRegex2)

        $tarih = ""
        if ($tarihMatch1.Success) {
            # YYYYMMDD formatında tarih
            $tarih = $tarihMatch1.Value
        } elseif ($tarihMatch2.Success) {
            # YYYY-MM-DD formatında tarih
            $tarih = $tarihMatch2.Value -replace "-", ""
        }

        if ($tarih -ne "") {
            # Tarihi ayıkla ve klasör yapısını oluştur
            $year = $tarih.Substring(0, 4)
            $month = $tarih.Substring(4, 2)
            $arsivPath = "$arsivRoot\$year\$month"
            if (!(Test-Path $arsivPath)) {
                New-Item -ItemType Directory -Path $arsivPath -Force
            }

            # Dosyayı taşımak için tam yol oluştur
            $destinationPath = "$arsivPath\$($file.Name)"
            Move-Item -Path $file.FullName -Destination $destinationPath
        } else {
            # Tarih bulunamadıysa tarihsiz klasörüne taşı
            $destinationPath = "$tarihsizPath\$($file.Name)"
            Move-Item -Path $file.FullName -Destination $destinationPath
        }
    }
}

